// ============================================================
// "BACKEND" SIMULADO — mesmas regras e formato de resposta do
// server.js real (status HTTP, JSON, hash de senha, token),
// rodando dentro do próprio navegador só pra testarmos o
// fluxo completo aqui no chat. Quando o backend real estiver
// no ar, essas 3 funções viram chamadas fetch() de verdade.
// ============================================================
async function hashSenha(senha) {
  const salt = crypto.getRandomValues(new Uint8Array(8)).reduce((s, b) => s + b.toString(16).padStart(2, "0"), "");
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(salt + senha));
  const hash = Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
  return `${salt}:${hash}`;
}
async function conferirSenha(senha, senhaHash) {
  const [salt, hash] = senhaHash.split(":");
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(salt + senha));
  const novoHash = Array.from(new Uint8Array(buf)).map((b) => b.toString(16).padStart(2, "0")).join("");
  return novoHash === hash;
}
function gerarToken(payload) {
  return btoa(JSON.stringify({ ...payload, criadoEm: Date.now() }));
}
function lerToken(token) {
  try { return JSON.parse(atob(token)); } catch { return null; }
}
// máscara (xx) xxxxx-xxxx aplicada enquanto o usuário digita
function formatarCelular(valor) {
  const d = (valor || "").replace(/\D/g, "").slice(0, 11);
  if (d.length === 0) return "";
  if (d.length < 3) return `(${d}`;
  if (d.length < 8) return `(${d.slice(0, 2)}) ${d.slice(2)}`;
  return `(${d.slice(0, 2)}) ${d.slice(2, 7)}-${d.slice(7)}`;
}
// no login aceitamos celular OU e-mail: só aplica a máscara se não parecer e-mail
function formatarContatoLogin(valor) {
  if (/[a-zA-Z@]/.test(valor)) return valor;
  return formatarCelular(valor);
}
// combina data + hora cadastradas do jogo e verifica se já passou (bloqueia palpite).
// uma vez true, fica true pra sempre — cobre o jogo em andamento E depois de encerrado, sem reabrir.
function jogoJaComecou(jogo) {
  if (!jogo || !jogo.data || !jogo.hora) return false;
  const inicio = new Date(`${jogo.data}T${jogo.hora}:00`);
  return new Date() >= inicio;
}

// Descobre qual é a "rodada atual" pra abrir por padrão nas telas de Postar Palpites / Palpites de Todos / Palpites da Rodada:
// 1) a rodada que o Admin liberou pra palpite agora, se houver uma;
// 2) senão, a rodada do próximo jogo que ainda vai começar (o mais próximo no tempo);
// 3) senão (todos os jogos já aconteceram, ou nenhum jogo cadastrado), a última rodada cadastrada.
function rodadaAtualNumero(lista) {
  if (!lista || lista.length === 0) return null;
  const liberado = lista.find((j) => j.liberado);
  if (liberado) return liberado.rodada;
  const futuros = [...lista]
    .filter((j) => !jogoJaComecou(j))
    .sort((a, b) => new Date(`${a.data}T${a.hora}:00`) - new Date(`${b.data}T${b.hora}:00`));
  if (futuros.length > 0) return futuros[0].rodada;
  return Math.max(...lista.map((j) => j.rodada));
}

// pontuação de um palpite comparado ao resultado final do jogo:
// 6 = cravada (placar exato) | 4 = vencedor certo + gols certos de um time
// 3 = vencedor/empate certo, sem acertar os gols | 1 = só acertou os gols de um time | 0 = nada
function classificarPalpite(pm, pv, rm, rv) {
  if (pm === rm && pv === rv) return 6;
  const real = rm > rv ? "M" : rm < rv ? "V" : "E";
  const apostado = pm > pv ? "M" : pm < pv ? "V" : "E";
  const acertouUmGol = pm === rm || pv === rv;
  if (apostado === real) return acertouUmGol ? 4 : 3;
  return acertouUmGol ? 1 : 0;
}

// selo de posição no ranking: coroa (1º), medalhas prata/bronze (2º/3º),
// número em destaque (4º/5º) e número em vermelho pros 4 últimos colocados
function RankBadge({ posicao, total }) {
  if (posicao === 1) return <Crown size={24} color="#F2C230" />;
  if (posicao === 2) return <div className="rank-medalha rank-prata">2</div>;
  if (posicao === 3) return <div className="rank-medalha rank-bronze">3</div>;
  if (posicao === 4 || posicao === 5) return <span className="rank-destaque">{posicao}</span>;
  if (total > 4 && posicao > total - 4) return <span className="rank-destaque rank-vermelho">{posicao}</span>;
  return <span className="rank-normal">{posicao}</span>;
}

