  // qualquer participante logado pode apostar; Admin também pode apostar em nome de outro participante
  async function apiSalvarPalpite(tok, { jogoId, placarMandante, placarVisitante, participanteIdAlvo }) {
    await delay(400);
    const payload = lerToken(tok);
    if (!payload) {
      const body = { erro: "Token inválido ou ausente." };
      registrarLog("POST", "/palpites", 401, body);
      return { status: 401, body };
    }
    let participanteId = payload.id;
    if (participanteIdAlvo && participanteIdAlvo !== payload.id) {
      if (!payload.isAdmin) {
        const body = { erro: "Só o Administrador pode registrar palpite em nome de outro participante." };
        registrarLog("POST", "/palpites", 403, body);
        return { status: 403, body };
      }
      participanteId = participanteIdAlvo;
    }
    const pm = Number(placarMandante), pv = Number(placarVisitante);
    if (placarMandante === "" || placarVisitante === "" || isNaN(pm) || isNaN(pv) || pm < 0 || pv < 0) {
      const body = { erro: "Informe um placar válido para os dois times." };
      registrarLog("POST", "/palpites", 400, body);
      return { status: 400, body };
    }
    jogosRef.current = (await carregarJogos()) ?? jogosRef.current;
    const jogo = jogosRef.current.find((j) => j.id === jogoId);
    if (!jogo) {
      const body = { erro: "Jogo não encontrado." };
      registrarLog("POST", "/palpites", 404, body);
      return { status: 404, body };
    }
    // REGRA 1: participante só posta/edita palpite se ESSA rodada estiver liberada pelo Admin.
    // O Admin está isento — pode registrar/editar palpite de qualquer rodada, a qualquer momento.
    if (!payload.isAdmin && !jogo.liberado) {
      const body = { erro: "Os palpites dessa rodada ainda não foram liberados pelo Administrador." };
      registrarLog("POST", "/palpites", 409, body);
      return { status: 409, body };
    }
    // REGRA 2: mesmo liberada, a rodada fecha pra participantes no instante exato do início da partida
    // (data/hora cadastradas) e continua fechada com o jogo em andamento e depois de encerrado — não reabre.
    // O Admin, de novo, está isento dessa trava.
    if (jogoJaComecou(jogo) && !payload.isAdmin) {
      const body = { erro: "Esse jogo já começou. Não é mais possível registrar ou alterar palpite." };
      registrarLog("POST", "/palpites", 409, body);
      return { status: 409, body };
    }
    palpitesRef.current = (await carregarPalpites()) ?? palpitesRef.current; // busca o estado mais atual salvo
    const existente = palpitesRef.current.find((p) => p.participanteId === participanteId && p.jogoId === jogoId);
    if (existente) {
      existente.placarMandante = pm;
      existente.placarVisitante = pv;
      existente.atualizadoEm = new Date().toISOString();
    } else {
      palpitesRef.current.push({
        id: crypto.randomUUID(), participanteId, jogoId,
        placarMandante: pm, placarVisitante: pv, atualizadoEm: new Date().toISOString(),
      });
    }
    await salvarPalpitesStorage(palpitesRef.current);
    invalidarTelasDerivadas(); // palpite de algum participante mudou: os totais/relatórios precisam recalcular
    registrarLog("POST", "/palpites", 200, { jogoId, participanteId, placarMandante: pm, placarVisitante: pv });
    return { status: 200, body: { ok: true } };
  }

  // targetId opcional: só o Admin pode consultar os palpites de outro participante
