  async function apiAtualizarPerfil(tok, { celular, email, novaSenha, foto }) {
    await delay(450);
    const payload = lerToken(tok);
    if (!payload) {
      const body = { erro: "Token inválido ou ausente." };
      registrarLog("PUT", "/perfil", 401, body);
      return { status: 401, body };
    }
    if (!celular.trim() || !email.trim()) {
      const body = { erro: "Preencha celular e e-mail." };
      registrarLog("PUT", "/perfil", 400, body);
      return { status: 400, body };
    }
    bancoRef.current = (await carregarParticipantes()) ?? bancoRef.current;
    const idx = bancoRef.current.findIndex((p) => p.id === payload.id);
    if (idx === -1) {
      const body = { erro: "Participante não encontrado." };
      registrarLog("PUT", "/perfil", 404, body);
      return { status: 404, body };
    }
    const atual = bancoRef.current[idx];
    const atualizado = { ...atual, celular: celular.trim(), email: email.trim(), foto_url: foto || atual.foto_url };
    if (novaSenha) atualizado.senha_hash = await hashSenha(novaSenha);
    bancoRef.current[idx] = atualizado;
    await salvarParticipantes(bancoRef.current);
    setUsers([...bancoRef.current]);
    const { senha_hash, ...semSenha } = atualizado;
    registrarLog("PUT", "/perfil", 200, { participante: { ...semSenha, foto_url: "(base64 da foto)" } });
    return { status: 200, body: { participante: semSenha } };
  }

