        // evita que uma resposta atrasada "pise" num dado mais recente e faça os jogos sumirem da tela
        if (res.status === 200 && jogosFetchIdRef.current === idDestaBusca) setJogos(res.body.jogos);
        setLoadingJogosLista(false);
