  async function handleExportarDados() {
    setLoadingExport(true);
    setCopiadoExport(false);
    try {
      const [participantesLidos, jogosLidos, palpitesLidos] = await Promise.all([
        carregarParticipantes(), carregarJogos(), carregarPalpites(),
      ]);
      const participantes = participantesLidos ?? bancoRef.current;
      const jogosSalvos = jogosLidos ?? jogosRef.current;
      const palpitesSalvos = palpitesLidos ?? palpitesRef.current;
      const pacote = {
        versao: 1,
        exportadoEm: new Date().toISOString(),
        participantes,
        jogos: jogosSalvos,
        palpites: palpitesSalvos,
      };
      const texto = JSON.stringify(pacote);
      setTextoExportado(texto);
      try {
        await navigator.clipboard.writeText(texto);
        setCopiadoExport(true);
      } catch {
        // se o clipboard falhar, o texto já fica visível na caixa pra copiar manualmente
      }
    } catch (err) {
      setTextoExportado("Erro ao exportar: " + err.message);
    } finally {
      setLoadingExport(false);
    }
  }

  async function handleImportarDados() {
    setImportErro(""); setImportSucesso("");
    if (!textoImportar.trim()) { setImportErro("Cole o texto exportado do link antigo primeiro."); return; }
    setLoadingImport(true);
    try {
      const pacote = JSON.parse(textoImportar);
      if (!pacote.participantes || !pacote.jogos || !pacote.palpites) {
        setImportErro("Texto inválido — não parece ser um pacote exportado do PALPITÃO/Bolão do Dragão.");
        setLoadingImport(false);
        return;
      }
      await Promise.all([
        salvarParticipantes(pacote.participantes),
        salvarJogos(pacote.jogos),
        salvarPalpitesStorage(pacote.palpites),
      ]);
      bancoRef.current = pacote.participantes;
      jogosRef.current = pacote.jogos;
      palpitesRef.current = pacote.palpites;
      jogosFetchIdRef.current++; // invalida qualquer busca antiga ainda em andamento
      setUsers([...pacote.participantes]);
      setJogos([...pacote.jogos].sort((a, b) => a.rodada - b.rodada));
      invalidarTelasDerivadas(); // importação troca TUDO — força recálculo de Pontuação, Classificação, Desempenho e Palpites de Todos
      setImportSucesso(
        `Importado com sucesso: ${pacote.participantes.length} participantes, ${pacote.jogos.length} jogos e ${pacote.palpites.length} palpites.`
      );
      setTextoImportar("");
    } catch (err) {
      setImportErro("Erro ao importar: o texto colado não é um JSON válido.");
    } finally {
      setLoadingImport(false);
    }
  }

  async function handleCopiarWhatsApp(jogo) {
    setGerandoWhatsAppId(jogo.id);
    setCopiadoWhatsApp(false);
    try {
      const res = await apiListarPalpitesDoJogo(token, jogo.id);
      const naoRegistrados = res.status === 200 ? res.body.naoRegistrados : [];
      setNaoRegistradosPorJogo((prev) => ({ ...prev, [jogo.id]: naoRegistrados }));

      const listaNomes = naoRegistrados.length > 0
        ? naoRegistrados.map((p) => `- ${p.nome}`).join("\n")
        : "Ninguém — todo mundo já postou! 🎉";
      const texto =
        `⏰ Faltam 15 minutos para fechar os palpites da Rodada ${String(jogo.rodada).padStart(2, "0")} ` +
        `(${jogo.mandante} x ${jogo.visitante})!\nAinda não postaram:\n${listaNomes}\nCorre lá! 🐉⚽`;

      setTextoWhatsApp(texto);
      setTextoWhatsAppId(jogo.id);

      try {
        await navigator.clipboard.writeText(texto);
        setCopiadoWhatsApp(true);
      } catch {
        // clipboard pode falhar no sandbox; o texto já fica visível na caixa pra copiar manualmente
      }
    } catch (err) {
      setTextoWhatsApp("Erro ao gerar a lista: " + err.message);
      setTextoWhatsAppId(jogo.id);
    } finally {
      setGerandoWhatsAppId(null);
    }
  }

