  function handleFotoEdit(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = () => {
      const img = new Image();
      img.onload = () => {
        const maxLado = 480;
        const escala = Math.min(1, maxLado / Math.max(img.width, img.height));
        const canvas = document.createElement("canvas");
        canvas.width = Math.round(img.width * escala);
        canvas.height = Math.round(img.height * escala);
        canvas.getContext("2d").drawImage(img, 0, 0, canvas.width, canvas.height);
        setFotoEdit(canvas.toDataURL("image/jpeg", 0.75));
      };
      img.onerror = () => setFotoEdit(reader.result);
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  }

  async function handleSalvarPerfil(e) {
    e.preventDefault();
    setPerfilErro(""); setPerfilSucesso("");
    if (!celularEdit.trim() || !emailEdit.trim()) { setPerfilErro("Preencha celular e e-mail."); return; }
    if (novaSenhaEdit && novaSenhaEdit !== confirmarNovaSenhaEdit) { setPerfilErro("As senhas não coincidem."); return; }
    setLoadingPerfil(true);
    try {
      const res = await apiAtualizarPerfil(token, {
        celular: celularEdit, email: emailEdit, novaSenha: novaSenhaEdit || null, foto: fotoEdit,
      });
      if (res.status === 200) {
        setCurrentUser(res.body.participante);
        setNovaSenhaEdit(""); setConfirmarNovaSenhaEdit("");
        setPerfilSucesso("Dados atualizados com sucesso!");
      } else {
        setPerfilErro(res.body.erro);
      }
    } catch (err) {
      setPerfilErro("Erro inesperado ao salvar perfil: " + err.message);
    } finally {
      setLoadingPerfil(false);
    }
  }

